export function createBetaExperience(api){
 const hud=document.createElement('section');hud.id='betaWorkspace';hud.innerHTML=`<div class="beta-heading"><span class="eyebrow">YOUR NEXT MOVE</span><h2>Find your beta.</h2><p>Choose a route. Set your height. Climb.</p><p id="betaFit" role="status"></p></div><div class="beta-actions"><label class="route-chooser">Your route<select id="quickRoute" aria-label="Choose a beta route"></select></label><button id="betaFine" aria-pressed="false">Edit moves</button><button id="betaPresent">Watch climb ↗</button></div><div class="beta-bottom"><span id="betaMoveStatus"></span><button id="betaEarlier" title="Move earlier">←</button><button id="betaLater" title="Move later">→</button><button id="betaContinue">Continue line</button><button id="betaRemove">Delete move</button><button id="betaUndo">Undo</button></div>`;document.body.append(hud);
 const stage=document.createElement('section');stage.id='betaPresentation';stage.hidden=true;stage.innerHTML=`<div class="stage-brand">β betaform</div><button id="exitPresentation">Back ×</button><div class="stage-controls"><button id="replayStage">Replay ↻</button></div>`;document.body.append(stage);
 const $=id=>document.getElementById(id);let presenting=false,lastMode='',lastRoute='',lastHud=0;
 const materials=new Map();function isolate(){for(const [m,o]of materials)Object.assign(m,o);materials.clear();for(const h of api.holds){const active=api.state().mode!=='beta'||api.keyForHold(h)===api.state().route;const tag=h.getObjectByName('routeMarker');if(tag)tag.visible=active;if(active||h.userData.type.startsWith('volume-'))continue;for(const m of Array.isArray(h.material)?h.material:[h.material]){materials.set(m,{opacity:m.opacity,transparent:m.transparent,depthWrite:m.depthWrite});Object.assign(m,{transparent:true,opacity:.12,depthWrite:false,needsUpdate:true});}}}
 function close(){presenting=false;stage.hidden=true;document.body.classList.remove('beta-presenting');api.stop();}
 $('quickRoute').onchange=e=>api.choose(e.target.value);
 $('betaFine').onclick=()=>{const on=document.body.classList.toggle('beta-fine');$('betaFine').setAttribute('aria-pressed',String(on));$('betaFine').textContent=on?'Done editing':'Edit moves';};
 $('betaContinue').onclick=api.continue;$('betaUndo').onclick=api.undo;$('betaRemove').onclick=api.remove;$('betaEarlier').onclick=api.earlier;$('betaLater').onclick=api.later;
 $('betaPresent').onclick=()=>{if(api.state().frames.length<2)return;api.stop();presenting=true;stage.hidden=false;document.body.classList.add('beta-presenting');api.focus(true);api.play();};
 $('exitPresentation').onclick=close;$('replayStage').onclick=()=>{api.stop();api.play();};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&presenting)close();});
 return{focus:api.focus,get presenting(){return presenting;},beginDrag(){},endDrag(){},update(t){const s=api.state();hud.hidden=s.mode!=='beta'||presenting;if(s.mode!==lastMode||s.route!==lastRoute){lastMode=s.mode;lastRoute=s.route;isolate();if(s.mode!=='beta'&&presenting)close();const source=$('betaRoute');$('quickRoute').replaceChildren(...[...source.options].map(o=>new Option(o.textContent.split(' · ').slice(0,2).join(' · '),o.value)));$('quickRoute').value=s.route;}
 if(t-lastHud<150)return;lastHud=t;$('betaPresent').disabled=s.frames.length<2;$('play').disabled=s.frames.length<2;$('betaFit').textContent=document.body.classList.contains('beta-fine')?'Drag a hand, foot or hip to adjust a move.':'';$('betaMoveStatus').textContent='Move '+(s.index+1)+' of '+s.frames.length;$('betaContinue').hidden=!s.editing&&s.index===s.frames.length-1;$('betaRemove').disabled=s.frames.length<2;$('betaEarlier').disabled=s.index===0;$('betaLater').disabled=s.index===s.frames.length-1;
 }};
}
